CREATE OR REPLACE FUNCTION "ponder_go_srcsync_18e196b54d2f0871"."_ponder_go_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'TRUNCATE is unsupported for onchain tables'; END IF;
